'use client';

import React, { useTransition } from 'react';
import { useForm, useFieldArray, Controller } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Plus, Trash2, Send, Save, BookOpen } from 'lucide-react';
import { CatalogItem, Profile, Budget } from '@/types/budget';

const budgetItemSchema = z.object({
  id: z.string(),
  titulo: z.string().min(1, 'El título del ítem es requerido'),
  descripcion: z.string().optional(),
  cantidad: z.number().min(0.01, 'La cantidad debe ser mayor a 0'),
  precio_unitario: z.number().min(0, 'El precio no puede ser negativo'),
  subtotal: z.number(),
});

const budgetFormSchema = z.object({
  numero_presupuesto: z.string().min(1, 'Número requerido'),
  cliente_nombre: z.string().min(2, 'El nombre del cliente es obligatorio'),
  cliente_telefono: z.string().min(6, 'Ingrese un teléfono válido'),
  cliente_direccion: z.string().optional(),
  items: z.array(budgetItemSchema).min(1, 'Debe incluir al menos un ítem'),
  subtotal: z.number().min(0),
  descuento: z.number().min(0).default(0),
  total: z.number().min(0),
  notas_condiciones: z.string().optional(),
});

type BudgetFormValues = z.infer<typeof budgetFormSchema>;

interface BudgetFormProps {
  profile: Profile;
  catalog: CatalogItem[];
  onSave: (data: Budget) => Promise<{ success: boolean; id?: string }>;
}

export const BudgetForm: React.FC<BudgetFormProps> = ({ profile, catalog, onSave }) => {
  const [isPending, startTransition] = useTransition();

  const {
    register,
    control,
    handleSubmit,
    watch,
    setValue,
    formState: { errors },
  } = useForm<BudgetFormValues>({
    resolver: zodResolver(budgetFormSchema),
    defaultValues: {
      numero_presupuesto: `PRES-${Math.floor(1000 + Math.random() * 9000)}`,
      cliente_nombre: '',
      cliente_telefono: '',
      cliente_direccion: '',
      items: [
        {
          id: crypto.randomUUID(),
          titulo: '',
          descripcion: '',
          cantidad: 1,
          precio_unitario: 0,
          subtotal: 0,
        },
      ],
      subtotal: 0,
      descuento: 0,
      total: 0,
      notas_condiciones: profile.condiciones_defecto || '',
    },
  });

  const { fields, append, remove } = useFieldArray({
    control,
    name: 'items',
  });

  const watchItems = watch('items');
  const watchDescuento = watch('descuento') || 0;

  // Recálculo dinámico en tiempo real
  const calculatedSubtotal = watchItems.reduce((acc, item) => {
    const qty = Number(item.cantidad) || 0;
    const price = Number(item.precio_unitario) || 0;
    return acc + qty * price;
  }, 0);

  const calculatedTotal = Math.max(0, calculatedSubtotal - (Number(watchDescuento) || 0));

  const handleSelectItemFromCatalog = (index: number, catalogId: string) => {
    const selected = catalog.find((c) => c.id === catalogId);
    if (selected) {
      setValue(`items.${index}.titulo`, selected.titulo);
      setValue(`items.${index}.descripcion`, selected.descripcion || '');
      setValue(`items.${index}.precio_unitario`, selected.precio_sugerido);
      
      const qty = watchItems[index]?.cantidad || 1;
      setValue(`items.${index}.subtotal`, qty * selected.precio_sugerido);
    }
  };

  const updateRowSubtotal = (index: number) => {
    const qty = watchItems[index]?.cantidad || 0;
    const price = watchItems[index]?.precio_unitario || 0;
    setValue(`items.${index}.subtotal`, qty * price);
  };

  const processFormSubmission = async (values: BudgetFormValues) => {
    const fullBudget: Budget = {
      ...values,
      user_id: profile.id,
      subtotal: calculatedSubtotal,
      total: calculatedTotal,
      estado: 'borrador',
      items: values.items.map((item) => ({
        ...item,
        subtotal: item.cantidad * item.precio_unitario,
      })),
    };

    return await onSave(fullBudget);
  };

  const onSubmitOnlySave = (values: BudgetFormValues) => {
    startTransition(async () => {
      const res = await processFormSubmission(values);
      if (res.success) {
        alert('Presupuesto guardado con éxito.');
      }
    });
  };

  const onSubmitAndWhatsApp = (values: BudgetFormValues) => {
    startTransition(async () => {
      const res = await processFormSubmission(values);
      if (res.success) {
        // Formatear mensaje para WhatsApp
        const cleanPhone = values.cliente_telefono.replace(/\D/g, '');
        const textMessage = encodeURIComponent(
          `Hola *${values.cliente_nombre}*! 👋\nTe adjunto la propuesta comercial de *${profile.nombre_comercial}* (Presupuesto N° *${values.numero_presupuesto}*).\n\n💰 *Total:* ${profile.moneda} $${calculatedTotal.toLocaleString()}\n\nPodés descargar el PDF detallado aquí:\n${window.location.origin}/api/pdf/${res.id || 'temp'}\n\nQuedamos a disposición!`
        );
        
        window.open(`https://wa.me/${cleanPhone}?text=${textMessage}`, '_blank');
      }
    });
  };

  return (
    <form className="max-w-4xl mx-auto p-4 md:p-6 space-y-6 bg-white rounded-xl shadow-sm border border-gray-100">
      {/* Encabezado Formulario */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center border-b pb-4 gap-2">
        <div>
          <h1 className="text-xl font-bold text-gray-900">Nuevo Presupuesto</h1>
          <p className="text-sm text-gray-500">Crea un presupuesto rápido e impecable</p>
        </div>
        <div className="w-full sm:w-auto">
          <input
            {...register('numero_presupuesto')}
            className="w-full sm:w-36 px-3 py-1.5 text-sm font-semibold text-right bg-gray-50 border rounded-lg"
          />
        </div>
      </div>

      {/* Secciona Datos del Cliente */}
      <div className="bg-gray-50/50 p-4 rounded-lg space-y-3 border border-gray-100">
        <h2 className="text-xs font-bold text-blue-600 uppercase tracking-wider">Datos del Cliente</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          <div>
            <label className="block text-xs font-medium text-gray-700 mb-1">Nombre Completo *</label>
            <input
              {...register('cliente_nombre')}
              placeholder="Ej: Juan Pérez"
              className="w-full text-sm px-3 py-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none"
            />
            {errors.cliente_nombre && <p className="text-xs text-red-500 mt-1">{errors.cliente_nombre.message}</p>}
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-700 mb-1">Teléfono (WhatsApp) *</label>
            <input
              {...register('cliente_telefono')}
              placeholder="Ej: 5491122334455"
              className="w-full text-sm px-3 py-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none"
            />
            {errors.cliente_telefono && <p className="text-xs text-red-500 mt-1">{errors.cliente_telefono.message}</p>}
          </div>

          <div className="md:col-span-2">
            <label className="block text-xs font-medium text-gray-700 mb-1">Dirección (Opcional)</label>
            <input
              {...register('cliente_direccion')}
              placeholder="Ej: Av. San Martín 1234, CABA"
              className="w-full text-sm px-3 py-2 border rounded-md focus:ring-2 focus:ring-blue-500 outline-none"
            />
          </div>
        </div>
      </div>

      {/* Ítems del Presupuesto */}
      <div className="space-y-4">
        <div className="flex justify-between items-center">
          <h2 className="text-xs font-bold text-blue-600 uppercase tracking-wider">Detalle de Ítems / Trabajo</h2>
        </div>

        {fields.map((field, index) => (
          <div key={field.id} className="p-3 bg-white border border-gray-200 rounded-lg space-y-3 relative">
            {/* Selector de Catálogo */}
            {catalog.length > 0 && (
              <div className="flex items-center gap-2">
                <BookOpen className="w-3.5 h-3.5 text-gray-400" />
                <select
                  onChange={(e) => handleSelectItemFromCatalog(index, e.target.value)}
                  defaultValue=""
                  className="text-xs bg-gray-50 border rounded px-2 py-1 text-gray-600 outline-none"
                >
                  <option value="" disabled>Autocompletar desde catálogo...</option>
                  {catalog.map((cat) => (
                    <option key={cat.id} value={cat.id}>{cat.titulo} (${cat.precio_sugerido})</option>
                  ))}
                </select>
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-12 gap-2">
              <div className="md:col-span-6">
                <input
                  {...register(`items.${index}.titulo`)}
                  placeholder="Título del ítem / servicio"
                  className="w-full text-sm px-3 py-1.5 border rounded-md outline-none font-medium"
                />
              </div>

              <div className="grid grid-cols-3 md:col-span-5 gap-2">
                <div>
                  <input
                    type="number"
                    step="any"
                    {...register(`items.${index}.cantidad`, {
                      valueAsNumber: true,
                      onChange: () => updateRowSubtotal(index),
                    })}
                    placeholder="Cant."
                    className="w-full text-sm px-2 py-1.5 border rounded-md text-center outline-none"
                  />
                </div>

                <div>
                  <input
                    type="number"
                    step="any"
                    {...register(`items.${index}.precio_unitario`, {
                      valueAsNumber: true,
                      onChange: () => updateRowSubtotal(index),
                    })}
                    placeholder="Precio"
                    className="w-full text-sm px-2 py-1.5 border rounded-md text-right outline-none"
                  />
                </div>

                <div className="flex items-center justify-end px-2 bg-gray-50 rounded text-sm font-semibold">
                  ${((watchItems[index]?.cantidad || 0) * (watchItems[index]?.precio_unitario || 0)).toLocaleString()}
                </div>
              </div>

              <div className="md:col-span-1 flex justify-end items-center">
                {fields.length > 1 && (
                  <button
                    type="button"
                    onClick={() => remove(index)}
                    className="p-1.5 text-red-500 hover:bg-red-50 rounded-md transition"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                )}
              </div>
            </div>

            <div>
              <textarea
                {...register(`items.${index}.descripcion`)}
                placeholder="Descripción detallada o especificaciones técnicas (opcional)"
                rows={1}
                className="w-full text-xs px-3 py-1.5 border border-dashed rounded-md outline-none text-gray-600"
              />
            </div>
          </div>
        ))}

        <button
          type="button"
          onClick={() =>
            append({
              id: crypto.randomUUID(),
              titulo: '',
              descripcion: '',
              cantidad: 1,
              precio_unitario: 0,
              subtotal: 0,
            })
          }
          className="w-full py-2.5 border-2 border-dashed border-blue-200 text-blue-600 text-sm font-medium rounded-lg flex items-center justify-center gap-2 hover:bg-blue-50 transition"
        >
          <Plus className="w-4 h-4" /> Agregar Ítem
        </button>
      </div>

      {/* Totales y Condiciones */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-4 border-t">
        <div>
          <label className="block text-xs font-medium text-gray-700 mb-1">Notas y Condiciones</label>
          <textarea
            {...register('notas_condiciones')}
            rows={3}
            className="w-full text-xs p-2.5 border rounded-md text-gray-600 outline-none"
          />
        </div>

        <div className="bg-gray-50 p-3.5 rounded-lg space-y-2">
          <div className="flex justify-between text-sm text-gray-600">
            <span>Subtotal:</span>
            <span className="font-semibold">${calculatedSubtotal.toLocaleString()}</span>
          </div>

          <div className="flex justify-between items-center text-sm text-gray-600">
            <span>Descuento:</span>
            <div className="w-28">
              <input
                type="number"
                {...register('descuento', { valueAsNumber: true })}
                className="w-full text-sm px-2 py-1 text-right border rounded outline-none"
              />
            </div>
          </div>

          <div className="flex justify-between text-base font-bold text-blue-900 border-t pt-2">
            <span>Total Final:</span>
            <span>${calculatedTotal.toLocaleString()} {profile.moneda}</span>
          </div>
        </div>
      </div>

      {/* Acciones Finales (Mobile First - Stack vertical en móvil, horizontal en desktop) */}
      <div className="flex flex-col sm:flex-row gap-3 pt-2">
        <button
          type="button"
          disabled={isPending}
          onClick={handleSubmit(onSubmitOnlySave)}
          className="w-full sm:w-1/2 py-3 bg-gray-100 hover:bg-gray-200 text-gray-800 font-semibold rounded-lg flex items-center justify-center gap-2 text-sm transition disabled:opacity-50"
        >
          <Save className="w-4 h-4" /> Guardar Solo
        </button>

        <button
          type="button"
          disabled={isPending}
          onClick={handleSubmit(onSubmitAndWhatsApp)}
          className="w-full sm:w-1/2 py-3 bg-green-600 hover:bg-green-700 text-white font-semibold rounded-lg flex items-center justify-center gap-2 text-sm transition shadow-sm disabled:opacity-50"
        >
          <Send className="w-4 h-4" /> Guardar y Enviar por WhatsApp
        </button>
      </div>
    </form>
  );
};